import bpy, os, json
from mathutils import Vector
from mathutils.bvhtree import BVHTree
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout'); tower=bpy.data.objects.get('V4 | torre documental'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador')
if not terrain or not tower or not hall: raise RuntimeError('anchors ausentes')
verts=[terrain.matrix_world@v.co for v in terrain.data.vertices]; polys=[tuple(p.vertices) for p in terrain.data.polygons]; bvh=BVHTree.FromPolygons(verts,polys,all_triangles=False)
def rayz(x,y):
    h=bvh.ray_cast(Vector((x,y,250)),Vector((0,0,-1)),600); return None if h[0] is None else float(h[0].z)
T=tower.matrix_world.translation.xy.copy(); H=hall.matrix_world.translation.xy.copy(); EX=(H-T).normalized(); EY=Vector((-EX.y,EX.x)); FRONT=-EX
line=[]
for s in range(-35,41,2):
    p=T+EX*s; z=rayz(p.x,p.y); line.append({'axis_m':s,'xy':[round(p.x,3),round(p.y,3)],'z':None if z is None else round(z,3)})
# grade lateral: eixos longitudinais deslocados transversalmente, útil para detectar o offset lateral errado da estação
grid=[]
for lat in (-15,-10,-5,0,5,10,15):
    row=[]
    for s in (-20,-15,-10,-5,0,5,10):
        p=T+EX*s+EY*lat; z=rayz(p.x,p.y); row.append({'s':s,'z':None if z is None else round(z,3)})
    grid.append({'lat_m':lat,'samples':row})
# candidatos importados relacionados ao Elevador e objetos próximos da torre
candidates=[]
for o in bpy.data.objects:
    n=o.name.lower(); props={k:o[k] for k in o.keys()}
    text=(o.name+' '+str(props)).lower()
    if 'elevador' in text or 'lacerda' in text or '59224731' in text:
        p=o.matrix_world.translation; candidates.append({'name':o.name,'type':o.type,'loc':[round(p.x,3),round(p.y,3),round(p.z,3)],'dims':[round(float(v),3) for v in o.dimensions],'collections':[c.name for c in o.users_collection],'props':props})
near=[]
for o in bpy.data.objects:
    p=o.matrix_world.translation.xy
    if (p-T).length<=30 and o not in (terrain,tower,hall):
        if o.type in {'MESH','CURVE','EMPTY'}:
            near.append({'name':o.name,'type':o.type,'dist_xy':round((p-T).length,3),'loc':[round(o.matrix_world.translation.x,3),round(o.matrix_world.translation.y,3),round(o.matrix_world.translation.z,3)],'collections':[c.name for c in o.users_collection]})
near=sorted(near,key=lambda r:r['dist_xy'])[:80]
report={'tower_xy':[round(T.x,6),round(T.y,6)],'hall_xy':[round(H.x,3),round(H.y,3)],'EX_tower_to_high':[round(EX.x,6),round(EX.y,6)],'EY_transverse':[round(EY.x,6),round(EY.y,6)],'axis_terrain':line,'lateral_grid':grid,'elevador_candidates':candidates,'near_tower':near}
print('ELEVADOR_AXIS_AUDIT_BEGIN'); print(json.dumps(report,ensure_ascii=False,separators=(',',':'),default=str)); print('ELEVADOR_AXIS_AUDIT_END')
